"""Writes sql/lucentbase-schema.sql, the reconstructed lucentBASE schema as MariaDB DDL.

    uv run python scripts/dump_schema.py
"""

from pathlib import Path

from sqlalchemy.dialects import mysql
from sqlalchemy.schema import CreateIndex, CreateTable

from lucentapi.schema import metadata

HEADER = """\
-- lucentBASE, reconstructed by lucentAPI from the column lists of lucentAndShiny's demo data.
-- Generated by scripts/dump_schema.py from src/lucentapi/schema.py; don't edit by hand.
-- Column names are exact, types are a best guess: compare with your own lucentBASE DDL.
-- It already contains the columns of lucentbase-additions.sql.
"""


def ddl() -> str:
    dialect = mysql.dialect(is_mariadb=True)
    statements = []
    for table in metadata.sorted_tables:
        statements.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";")
        for index in sorted(table.indexes, key=lambda i: i.name):
            statements.append(str(CreateIndex(index).compile(dialect=dialect)).strip() + ";")
    return HEADER + "\n" + "\n\n".join(statements) + "\n"


if __name__ == "__main__":
    target = Path(__file__).parent.parent / "sql" / "lucentbase-schema.sql"
    target.write_text(ddl())
    print(f"wrote {target}")
